function missingRanges(arr, n) {
  const set = new Set(arr);
  const ranges = [];
  let start = 1;
  for (let i = 1; i <= n; i++) {
    if (!set.has(i)) {
      if (start === i) {
        let end = i;
        while (end <= n && !set.has(end + 1)) end++;
        ranges.push([start, end]);
        start = end + 1;
        i = end;
      }
    } else {
      start = i + 1;
    }
  }
  return ranges;
}
